"""ARM Y and ARM Z report, generated from the JSON (never typed):
results/ys/army_scores.json, results/zs/armz_scores.json, results/xs/armx_scores.json,
results/ys/c5_render_labels.json, results/zs/offset_check.json.

    env/bin/python3 ops/yz_report.py   ->   results/ys/ARMYZ_REPORT.md
"""
import json, pathlib
import numpy as np
R = pathlib.Path(__file__).resolve().parents[1]
J = lambda p: json.loads((R / p).read_text())
Y, Z, X = J("results/ys/army_scores.json"), J("results/zs/armz_scores.json"), J("results/xs/armx_scores.json")
C5, OC = J("results/ys/c5_render_labels.json"), J("results/zs/offset_check.json")
P = "hybrid_3d2d-seed42_step-075000"; SEG = ["w00", "ag144", "ag174"]; XS = {k: "p0841_" + k for k in SEG}
f4 = lambda v: "n/a" if v is None or (isinstance(v, float) and np.isnan(v)) else f"{v:.4f}"
yprod = {k: f"w{Y['segments'][k]['prep']['production_window'][0]:02d}" for k in SEG}
L = ["# ARM Y and ARM Z: the same PHerc0841 segments on three organiser arrays", "",
     "Generated by `ops/yz_report.py` from the JSON. Pre-registrations: `results/ys/PREREGISTRATION_ARMY.md`, `results/zs/PREREGISTRATION_ARMZ.md`.", "",
     "## One checkpoint, three arrays", "",
     "ink_9um seed42 step-075000, both depth directions, label-free choice (larger separation). AUC against the organisers' labels.", "",
     "| array | w00 | ag144 | ag174 | median | order the labels prefer |", "|---|---|---|---|---|---|"]
def row(name, get):
    v = [get(k) for k in SEG]; ords = sorted({o for _, _, o in v})
    L.append(f"| {name} | " + " | ".join(f4(a) for a, _, _ in v) + f" | **{f4(float(np.median([a for a, _, _ in v])))}** | {', '.join(ords)} on all three |" if len(ords) == 1 else
             f"| {name} | " + " | ".join(f4(a) for a, _, _ in v) + f" | **{f4(float(np.median([a for a, _, _ in v])))}** | mixed |")
def pick(r): return r["auc_chosen"], r["chosen"], ("stored" if r["forward"]["auc"] >= r["reverse"]["auc"] else "reversed")
row("4.681 um render, label bucket (ARM X)", lambda k: pick(X["segments"][XS[k]]["rows"][P]))
row("2.403 um surface volume, production 9 um recipe (ARM Y)", lambda k: pick(Y["segments"][k]["windows"][yprod[k]][P]))
row("9.366 um surface volume, eligible scan (ARM Z)", lambda k: pick(Z["segments"][k]["rows"][P]))
L += ["", f"In distribution, the same checkpoint scores **{f4(Y['Y2']['c1_in_distribution'])}** on PHerc0139 w016 (ARM X, C1). "
      "The render row is scored against the label files that sit beside the renders in the label bucket; the two surface-volume rows use "
      "the published 20260918 labels, moved onto the 9.366 um canvas for the last row. The controls below check both label sets.", "",
      "Stored order against reversed, same checkpoint:", "", "| array | w00 | ag144 | ag174 |", "|---|---|---|---|"]
fr = lambda r: f"{f4(r['forward']['auc'])} / {f4(r['reverse']['auc'])}"
L.append("| 4.681 um render | " + " | ".join(fr(X["segments"][XS[k]]["rows"][P]) for k in SEG) + " |")
L.append("| 2.403 um volume | " + " | ".join(fr(Y["segments"][k]["windows"][yprod[k]][P]) for k in SEG) + " |")
L.append("| 9.366 um volume | " + " | ".join(fr(Z["segments"][k]["rows"][P]) for k in SEG) + " |")
_gap = {k: Y["segments"][k]["windows"][yprod[k]][P]["auc_chosen"] - Z["segments"][k]["rows"][P]["auc_chosen"] for k in SEG}
L += ["", "Same labels, same segments, two representation families in villa's own terms (#1582): `public_2p4_level2_zmean4` minus "
      "`native` 9.366 um, " + ", ".join(f"{k} {_gap[k]:+.4f}" for k in SEG) + f"; the pooled family is ahead on {sum(v > 0 for v in _gap.values())} of 3."]
L += ["", "## Verdicts, as pre-registered", "",
      f"- Y1, direction: **{Y['Y1']['verdict']}**",
      f"- Y2, array: **{Y['Y2']['verdict']}** (median {f4(Y['Y2']['published_median'])} on the 2.403 um volumes against {f4(Y['Y2']['render_median'])} on the renders)",
      f"- Z1, eligible scan: **{Z['Z1']['verdict']}** (median {f4(Z['Z1']['eligible_median'])})"]
if "Y3" in Y:
    L.append(f"- Y3, slice: **{Y['Y3']['verdict']}**")
L += ["", "## Controls", ""]
L.append("- C4, the swept production window equals villa's own recipe bit for bit: " + ", ".join(f"{k} {'PASS' if Y['segments'][k]['prep']['C4']['pass_'] else 'FAIL'}" for k in SEG))
L.append("- C3, the organisers' own published prediction scored on the same labels and grid (bar 0.75): " + ", ".join(f"{k} {f4(Y['segments'][k]['C3']['auc'])}" for k in SEG))
L.append(f"- Direction rule reproduces every stored ARM X choice: {Y['CHOOSE_EQ']['rows'] - Y['CHOOSE_EQ']['disagreements']} of {Y['CHOOSE_EQ']['rows']}")
for nm, src in (("2.403 um", lambda k: Y["segments"][k].get("C2_shuffle")), ("9.366 um", lambda k: Z["segments"][k].get("C2_shuffle"))):
    L.append(f"- C2 block-shuffle floor, {nm}, 20 seeds: " + ", ".join(f"{k} median {f4(float(np.median(src(k))))} (range {f4(min(src(k)))} to {f4(max(src(k)))})" for k in SEG if src(k)))
L.append("- Z-ALIGN, 9.366 um canvas against the 2.403 um canvas: " + ", ".join(
    f"{k} offset {tuple(Z['segments'][k]['meta']['zalign']['used_offset'])} px, peak NCC {f4(Z['segments'][k]['meta']['zalign']['peak_ncc'])}, NCC at zero {f4(Z['segments'][k]['meta']['zalign']['ncc_at_zero'])}" for k in SEG))
L += ["", "Added after the result and not pre-registered:", ""]
L.append("- Label offset sensitivity on the 9.366 um grid: the best offset within 2 px of the one used gains at most "
         f"{f4(max(OC[k]['best_auc'] - OC[k]['auc_used'] for k in SEG))}, and zero offset loses at most {f4(max(OC[k]['auc_used'] - OC[k]['zero_offset_auc'] for k in SEG))}.")
sc = {f: v for f, v in C5.items() if "auc" in v}
L.append("- The render labels are sound: on the w00 render the organisers' own stored predictions score " +
         ", ".join(f"`{f}` {f4(v['auc'])}" for f, v in sc.items()) + ".")
if "Y3" in Y or "Y3_partial" in Y:
    y3 = Y.get("Y3", {}).get("per_segment") or Y["Y3_partial"]
    wins = sorted({w for k in SEG for w in Y["segments"][k]["windows"] if P in Y["segments"][k]["windows"][w] and "chosen" in Y["segments"][k]["windows"][w][P]})
    if len(wins) > 1:
        L += ["", "## The 84-plane window swept across the 109 layers (2.403 um, label-free direction)", "",
              "| segment | " + " | ".join(f"planes {int(w[1:])} to {int(w[1:]) + 83}" for w in wins) + " |", "|---|" + "---|" * len(wins)]
        for k in SEG:
            W = Y["segments"][k]["windows"]
            L.append(f"| {k} | " + " | ".join((f"**{f4(W[w][P]['auc_chosen'])}**" if w == yprod[k] else f4(W[w][P]["auc_chosen"])) + ("" if W[w][P]["chosen"] == "forward" else " (rev)") for w in wins) + " |")
        L.append(""); L.append("Bold is villa's production window. " + " ".join(f"{k}: best {y3[k]['best_window']} ({f4(y3[k]['best_auc'])}), gain {f4(y3[k]['gain'])}." for k in SEG))
if "ALLCKPT" in Y:
    A = Y["ALLCKPT"]; ck = sorted(A["published_median"]); ZA = Z.get("ALLCKPT")
    L += ["", "## Every checkpoint (production window, label-free direction)", "",
          "| checkpoint | in distribution (C1), as pre-registered | C1, correct direction | PHerc0841 median, render | PHerc0841 median, 2.403 um volume |"
          + (" PHerc0841 median, eligible 9.366 um |" if ZA else ""), "|---|---|---|---|---|" + ("---|" if ZA else "")]
    for c in ck:
        L.append(f"| {c.replace('hybrid_3d2d-', '')} | {f4(A['c1'][c])} | {f4(A['c1_oracle'][c])} | {f4(A['render_median'][c])} | {f4(A['published_median'][c])} |"
                 + (f" {f4(ZA['eligible_median'][c])} |" if ZA else ""))
    if ZA and "ensemble_seed42+43_final" in ZA["eligible_median"]:
        L.append(f"| the two finals averaged | | | | | {f4(ZA['eligible_median']['ensemble_seed42+43_final'])} |")
    wrong = ", ".join(c.replace("hybrid_3d2d-", "") for c in A["c1_rule_wrong"])
    L += ["", f"On C1 the label-free direction rule chose the wrong direction for {len(A['c1_rule_wrong'])} of the 14 ({wrong}), which is why the first two "
          "columns differ; the correct-direction column was added after the fact. On the 2.403 um volumes the rule kept the better direction in "
          f"**{A['direction_rule_kept_better'][0]} of {A['direction_rule_kept_better'][1]}** (segment, checkpoint) pairs"
          + (f", on the eligible volumes in **{ZA['direction_rule_kept_better'][0]} of {ZA['direction_rule_kept_better'][1]}**" if ZA else "") + ".", "",
          "Does anything cheap rank the checkpoints the way the published volumes do? Spearman across the 14:", "",
          "| against | 2.403 um median |" + (" eligible 9.366 um median |" if ZA else ""), "|---|---|" + ("---|" if ZA else ""),
          f"| C1, as pre-registered | {f4(A['spearman_c1_vs_published'])} |" + (f" {f4(ZA['Z2_spearman_c1_vs_eligible'])} |" if ZA else ""),
          f"| C1, correct direction | {f4(A['spearman_c1oracle_vs_published'])} |" + (f" {f4(ZA['Z2_spearman_c1oracle_vs_eligible'])} |" if ZA else ""),
          f"| render median | {f4(A['spearman_render_vs_published'])} |" + (f" {f4(ZA['Z3_spearman_render_vs_eligible'])} |" if ZA else ""),
          f"| training step, seed42 | {f4(A['spearman_step_vs_published']['seed42'])} |" + (f" {f4(ZA['spearman_step_vs_eligible']['seed42'])} |" if ZA else ""),
          f"| training step, seed43 | {f4(A['spearman_step_vs_published']['seed43'])} |" + (f" {f4(ZA['spearman_step_vs_eligible']['seed43'])} |" if ZA else "")]
    if ZA and "Z3_spearman_2403_vs_eligible" in ZA:
        L.append(f"| 2.403 um median | | {f4(ZA['Z3_spearman_2403_vs_eligible'])} |")
    L += ["", f"Best single checkpoint on the 2.403 um volumes: {A['best_single'].replace('hybrid_3d2d-', '')} (**{f4(A['best_single_median'])}**)"
          + (f"; on the eligible volumes: {ZA['Z4_best_single'].replace('hybrid_3d2d-', '')} (**{f4(ZA['Z4_best_single_median'])}**), and the two finals "
             f"averaged give **{f4(ZA['Z4_ensemble_finals'])}**" if ZA else "") + "."]
    if ZA:
        _pairs = [(k, c) for k in SEG for c in ck if c in Z["segments"][k]["rows"] and c in Y["segments"][k]["windows"][yprod[k]]]
        _d = [Y["segments"][k]["windows"][yprod[k]][c]["auc_chosen"] - Z["segments"][k]["rows"][c]["auc_chosen"] for k, c in _pairs]
        L += ["", f"Family gap over every (segment, checkpoint) pair: the pooled 2.4 um family is ahead in **{sum(x > 0 for x in _d)} of {len(_d)}**, "
              f"median {f4(float(np.median(_d)))}, range {f4(min(_d))} to {f4(max(_d))}."]
(R / "results" / "ys" / "ARMYZ_REPORT.md").write_text("\n".join(L) + "\n")
print("\n".join(L))
